function safe(value){return String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function formatTradeName(trade){return String(trade||'').split('-').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');}
function slugify(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');}
async function loadDashboard(){try{
 const [accountRes,progressRes]=await Promise.all([fetch('/api/account'),fetch('/api/progress-summary')]);
 if(!accountRes.ok)throw new Error('Account unavailable');const account=await accountRes.json();const progress=progressRes.ok?await progressRes.json():{};
 document.getElementById('loader').style.display='none';document.getElementById('content').style.display='block';
 const name=(account.name||'').split(' ')[0]||'there';document.getElementById('dashboardGreeting').textContent=`Welcome back, ${name}`;
 const readiness=Math.max(0,Math.min(100,Number(progress.averageScore)||0));document.getElementById('dashboardReadinessRing').style.setProperty('--score',readiness);document.getElementById('dashboardReadinessScore').textContent=readiness?`${readiness}%`:'—';document.getElementById('dashboardReadinessText').textContent=progress.passProbability||'Complete more quizzes to build your estimate.';
 const trades=account.trades||[];const primary=trades[0]?.trade||(progress.tradeStats||[]).sort((a,b)=>b.attempts-a.attempts)[0]?.trade||'';
 const continueLink=document.getElementById('dashboardContinue');if(primary){continueLink.href=`/private/${primary}.html`;continueLink.textContent=`Continue ${formatTradeName(primary)}`;}
 document.getElementById('accountInfo').innerHTML=`<div class="rsp7-profile-list"><div class="rsp7-profile-row"><span>Name</span><strong>${safe(account.name||'User')}</strong></div><div class="rsp7-profile-row"><span>Email</span><strong>${safe(account.email||'')}</strong></div><div class="rsp7-profile-row"><span>Province</span><strong><a href="/provinces/${slugify(account.province||'British Columbia')}">${safe(account.province||'British Columbia')}</a></strong></div><div class="rsp7-profile-row"><span>Status</span><strong>Active</strong></div></div>`;
 document.getElementById('statsGrid').innerHTML=`<div class="rsp7-stat-grid"><div class="rsp7-stat"><small>Attempts</small><strong>${progress.totalAttempts||0}</strong></div><div class="rsp7-stat"><small>Average</small><strong>${progress.averageScore||0}%</strong></div><div class="rsp7-stat"><small>Best</small><strong>${progress.bestScore||0}%</strong></div><div class="rsp7-stat"><small>Active trades</small><strong>${trades.length}</strong></div></div>`;
 document.getElementById('tradeList').innerHTML=trades.length?`<div class="active-trade-grid">${trades.map(t=>`<article class="active-trade-card rsp7-lift"><div class="trade-card-head"><span class="trade-avatar">${safe(formatTradeName(t.trade).charAt(0))}</span><span class="active-dot">Active</span></div><h3>${safe(formatTradeName(t.trade))}</h3><p>Access until ${new Date(t.expiresAt).toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'})}</p><a href="/private/${safe(t.trade)}.html" class="open-trade-btn">Continue learning <span>→</span></a></article>`).join('')}</div>`:`<div class="empty-state"><strong>Choose your first trade</strong><p>Start free or unlock complete practice and progress tracking.</p><a href="/trades">Explore trades</a></div>`;
 const weak=progress.weakAreas||[];document.getElementById('weakAreaList').innerHTML=weak.length?`<div class="rsp7-weak-list">${weak.slice(0,4).map(w=>{const pct=Math.max(0,Math.min(100,Number(w.percentage)||0));return `<div class="rsp7-weak-item"><strong>${safe(w.category)}</strong><div class="rsp7-weak-bar"><span style="width:${100-pct}%"></span></div><small>${pct}% accuracy · ${w.mistakes||0} mistakes</small><div class="rsp7-weak-links"><a href="/trades/${safe(primary||'carpentry')}/study-guide">Review guide</a><a href="/trades/${safe(primary||'carpentry')}">Practise topic</a></div></div>`}).join('')}</div>`:`<p class="muted">Complete a quiz to receive personalized focus topics.</p>`;
 const attempts=progress.recentAttempts||[];document.getElementById('recentAttempts').innerHTML=attempts.length?`<div class="rsp7-attempt-list">${attempts.slice(0,6).map(a=>`<div class="rsp7-attempt"><div><strong>${safe(formatTradeName(a.trade))}</strong><small style="display:block;color:#718099">${a.correctAnswers}/${a.totalQuestions} correct · ${new Date(a.createdAt).toLocaleDateString()}</small></div><span class="rsp7-attempt-score">${a.percentage}%</span></div>`).join('')}</div>`:`<div class="empty-state"><strong>No attempts yet</strong><p>Take a free practice test to create your first performance insight.</p><a href="/practice-tests">Start free practice</a></div>`;
 const weakest=weak[0];document.getElementById('recommendedNext').innerHTML=primary?`<div class="rsp7-next-card"><span class="eyebrow">NEXT BEST ACTION</span><h3>${weakest?`Improve ${safe(weakest.category)}`:`Continue ${safe(formatTradeName(primary))}`}</h3><p>${weakest?`Review your weakest topic, then complete another practice set to check improvement.`:`Open your trade and continue building exam readiness.`}</p><a href="${weakest?`/trades/${safe(primary)}/study-guide`:`/private/${safe(primary)}.html`}">${weakest?'Review study guide':'Resume studying'} →</a></div>`:`<div class="rsp7-next-card"><span class="eyebrow">GET STARTED</span><h3>Choose a trade</h3><p>Find the right trade, try free questions, and build your personalized dashboard.</p><a href="/find-my-trade">Find my trade →</a></div>`;
}catch(err){document.getElementById('loader').innerHTML='<div class="loader-card"><div class="muted">Could not load your dashboard. Please refresh and try again.</div></div>';}}
async function deleteAccount(){const btn=document.getElementById('deleteAccountBtn'),password=document.getElementById('deletePassword').value,msg=document.getElementById('deleteMessage');if(!password){msg.textContent='Please enter your password.';msg.className='message error';return}if(!confirm('Are you sure you want to permanently delete your account?'))return;btn.disabled=true;btn.textContent='Deleting…';try{const res=await fetch('/delete-account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const data=await res.json();if(data.success){msg.textContent='Account deleted successfully.';msg.className='message success';setTimeout(()=>location='/signup',1000)}else{msg.textContent=data.message||'Failed to delete account.';msg.className='message error'}}finally{btn.disabled=false;btn.textContent='Delete My Account'}}
document.getElementById('deleteAccountBtn')?.addEventListener('click',deleteAccount);loadDashboard();